package com.saumyasolar.service;
import com.saumyasolar.api.OperationsModels.*;import com.saumyasolar.domain.*;import com.saumyasolar.repo.*;import com.saumyasolar.security.Principal;
import jakarta.transaction.Transactional;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.web.server.ResponseStatusException;
import java.math.BigDecimal;import java.time.Instant;import java.time.LocalDate;import java.util.*;
@Service
public class OperationsService{
private final CustomerOrderRepository orders;private final OrderItemRepository orderItems;private final OrderStatusHistoryRepository orderHistory;private final WarehouseRepository warehouses;private final InventoryBalanceRepository balances;private final InventoryTransactionRepository transactions;private final InventoryReservationRepository reservations;private final ProductRepository products;private final PackageItemRepository packageItems;private final InstallationJobRepository installations;private final InstallationChecklistItemRepository checklist;private final WarrantyRepository warranties;private final AppUserRepository users;
public OperationsService(CustomerOrderRepository a,OrderItemRepository b,OrderStatusHistoryRepository c,WarehouseRepository d,InventoryBalanceRepository e,InventoryTransactionRepository f,InventoryReservationRepository g,ProductRepository h,PackageItemRepository i,InstallationJobRepository j,InstallationChecklistItemRepository k,WarrantyRepository l,AppUserRepository m){orders=a;orderItems=b;orderHistory=c;warehouses=d;balances=e;transactions=f;reservations=g;products=h;packageItems=i;installations=j;checklist=k;warranties=l;users=m;}
private UUID tenant(Principal p){if(!"VENDOR".equals(p.accountType())||p.tenantId()==null)throw new ResponseStatusException(HttpStatus.FORBIDDEN);return p.tenantId();}
private void permission(Principal p,String code){if(p.permissions()==null||!p.permissions().contains(code))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Missing permission: "+code);}
private CustomerOrder order(UUID id,UUID t){return orders.findByIdAndTenantId(id,t).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Order not found"));}
private Warehouse warehouse(UUID id,UUID t){return warehouses.findByIdAndTenantId(id,t).filter(Warehouse::isActive).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Warehouse not found"));}
private Product product(UUID id,UUID t){return products.findByIdAndTenantId(id,t).filter(Product::isActive).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Product not found"));}
private InventoryBalance balance(UUID t,UUID w,UUID pr){return balances.findByTenantIdAndWarehouseIdAndProductId(t,w,pr).orElseGet(()->{InventoryBalance b=new InventoryBalance();b.setId(UUID.randomUUID());b.setTenantId(t);b.setWarehouseId(w);b.setProductId(pr);b.setOnHand(BigDecimal.ZERO);b.setReserved(BigDecimal.ZERO);b.setDamaged(BigDecimal.ZERO);return b;});}
private void movement(UUID t,UUID w,UUID pr,UUID o,UUID ins,String type,BigDecimal delta,String reason,UUID actor){InventoryTransaction x=new InventoryTransaction();x.setId(UUID.randomUUID());x.setTenantId(t);x.setWarehouseId(w);x.setProductId(pr);x.setOrderId(o);x.setInstallationId(ins);x.setType(type);x.setQuantityDelta(delta);x.setReason(reason);x.setActorId(actor);x.setCreatedAt(Instant.now());transactions.save(x);}
public List<Warehouse> warehouses(Principal p){permission(p,"INVENTORY_MANAGE");return warehouses.findByTenantIdOrderByNameAsc(tenant(p));}
@Transactional public Warehouse createWarehouse(WarehouseInput x,Principal p){UUID t=tenant(p);permission(p,"INVENTORY_MANAGE");Warehouse w=new Warehouse();w.setId(UUID.randomUUID());w.setTenantId(t);w.setCode(x.code().trim().toUpperCase(Locale.ROOT));w.setName(x.name().trim());w.setAddress(x.address());w.setActive(true);w.setCreatedAt(Instant.now());return warehouses.save(w);}
public List<InventoryBalance> balances(Principal p){permission(p,"INVENTORY_MANAGE");return balances.findByTenantIdOrderByWarehouseIdAscProductIdAsc(tenant(p));}
public List<InventoryTransaction> ledger(Principal p){permission(p,"INVENTORY_MANAGE");return transactions.findByTenantIdOrderByCreatedAtDesc(tenant(p));}
@Transactional public InventoryBalance receive(ReceiptInput x,Principal p){UUID t=tenant(p);permission(p,"INVENTORY_MANAGE");warehouse(x.warehouseId(),t);product(x.productId(),t);warehouses.findForUpdate(x.warehouseId(),t).orElseThrow();InventoryBalance b=balance(t,x.warehouseId(),x.productId());b.setOnHand(b.getOnHand().add(x.quantity()));balances.save(b);movement(t,x.warehouseId(),x.productId(),null,null,"RECEIPT",x.quantity(),x.reason(),p.userId());return b;}
@Transactional public InventoryBalance adjust(AdjustmentInput x,Principal p){UUID t=tenant(p);permission(p,"INVENTORY_MANAGE");warehouse(x.warehouseId(),t);product(x.productId(),t);warehouses.findForUpdate(x.warehouseId(),t).orElseThrow();InventoryBalance b=balance(t,x.warehouseId(),x.productId());BigDecimal delta="INCREASE".equals(x.direction())?x.quantity():x.quantity().negate();if(b.getAvailable().add(delta).signum()<0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Adjustment would make available stock negative");b.setOnHand(b.getOnHand().add(delta));balances.save(b);movement(t,x.warehouseId(),x.productId(),null,null,"ADJUSTMENT_"+x.direction(),delta,x.reason(),p.userId());return b;}
@Transactional public Map<String,Object> transfer(TransferInput x,Principal p){UUID t=tenant(p);permission(p,"INVENTORY_MANAGE");if(x.sourceWarehouseId().equals(x.targetWarehouseId()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Choose two different warehouses");warehouse(x.sourceWarehouseId(),t);warehouse(x.targetWarehouseId(),t);product(x.productId(),t);UUID first=x.sourceWarehouseId().compareTo(x.targetWarehouseId())<0?x.sourceWarehouseId():x.targetWarehouseId(),second=first.equals(x.sourceWarehouseId())?x.targetWarehouseId():x.sourceWarehouseId();warehouses.findForUpdate(first,t).orElseThrow();warehouses.findForUpdate(second,t).orElseThrow();InventoryBalance from=balance(t,x.sourceWarehouseId(),x.productId());if(from.getAvailable().compareTo(x.quantity())<0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Insufficient available stock");from.setOnHand(from.getOnHand().subtract(x.quantity()));balances.save(from);InventoryBalance to=balance(t,x.targetWarehouseId(),x.productId());to.setOnHand(to.getOnHand().add(x.quantity()));balances.save(to);movement(t,x.sourceWarehouseId(),x.productId(),null,null,"TRANSFER_OUT",x.quantity().negate(),x.reason(),p.userId());movement(t,x.targetWarehouseId(),x.productId(),null,null,"TRANSFER_IN",x.quantity(),x.reason(),p.userId());return Map.of("source",from,"target",to);}
@Transactional public List<InventoryReservation> reserve(UUID orderId,ReservationInput x,Principal p){UUID t=tenant(p);permission(p,"INVENTORY_MANAGE");CustomerOrder o=order(orderId,t);if(!Set.of("CONFIRMED","PAYMENT_PENDING","PAYMENT_PARTIAL","PAID","MATERIAL_RESERVED").contains(o.getStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Order is not eligible for material reservation");Warehouse w=warehouse(x.warehouseId(),t);warehouses.findForUpdate(w.getId(),t).orElseThrow();Map<UUID,BigDecimal> required=new LinkedHashMap<>();for(OrderItem line:orderItems.findByTenantIdOrderByIdDesc(t).stream().filter(i->i.getOrderId().equals(orderId)).toList()){if(line.getProductId()!=null)required.merge(line.getProductId(),BigDecimal.valueOf(line.getQuantity()),BigDecimal::add);else if(line.getPackageId()!=null)for(PackageItem pi:packageItems.findByTenantIdOrderByIdDesc(t).stream().filter(i->i.getPackageId().equals(line.getPackageId())&&!i.isOptionalItem()).toList())required.merge(pi.getProductId(),BigDecimal.valueOf((long)pi.getQuantity()*line.getQuantity()),BigDecimal::add);}if(required.isEmpty())throw new ResponseStatusException(HttpStatus.CONFLICT,"No stock-managed product components found on order");List<InventoryBalance> locked=new ArrayList<>();for(UUID id:required.keySet()){product(id,t);InventoryBalance b=balances.findForUpdate(t,w.getId(),id).orElseGet(()->balance(t,w.getId(),id));locked.add(b);}int n=0;for(var entry:required.entrySet()){if(locked.get(n++).getAvailable().compareTo(entry.getValue())<0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Insufficient stock for product "+entry.getKey());}List<InventoryReservation> out=new ArrayList<>();n=0;for(var entry:required.entrySet()){InventoryBalance b=locked.get(n++);b.setReserved(b.getReserved().add(entry.getValue()));balances.save(b);InventoryReservation r=new InventoryReservation();r.setId(UUID.randomUUID());r.setTenantId(t);r.setOrderId(orderId);r.setWarehouseId(w.getId());r.setProductId(entry.getKey());r.setQuantity(entry.getValue());r.setStatus("RESERVED");r.setCreatedAt(Instant.now());r.setUpdatedAt(Instant.now());out.add(reservations.save(r));movement(t,w.getId(),entry.getKey(),orderId,null,"RESERVATION",entry.getValue().negate(),"Order reservation: "+x.reason(),p.userId());}String old=o.getStatus();o.setStatus("MATERIAL_RESERVED");orders.save(o);status(o,old,p,"Stock reserved: "+x.reason());return out;}
@Transactional public List<InventoryReservation> release(UUID orderId,String reason,Principal p){UUID t=tenant(p);permission(p,"INVENTORY_MANAGE");CustomerOrder o=order(orderId,t);List<InventoryReservation> rows=reservations.findByTenantIdAndOrderId(t,orderId).stream().filter(r->"RESERVED".equals(r.getStatus())).toList();if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.CONFLICT,"No active reservations");for(InventoryReservation r:rows){warehouses.findForUpdate(r.getWarehouseId(),t).orElseThrow();InventoryBalance b=balances.findForUpdate(t,r.getWarehouseId(),r.getProductId()).orElseThrow();b.setReserved(b.getReserved().subtract(r.getQuantity()));balances.save(b);r.setStatus("RELEASED");r.setUpdatedAt(Instant.now());reservations.save(r);movement(t,r.getWarehouseId(),r.getProductId(),orderId,null,"RELEASE",r.getQuantity(),reason,p.userId());}String old=o.getStatus();o.setStatus("CONFIRMED");orders.save(o);status(o,old,p,reason);return rows;}
private void status(CustomerOrder o,String old,Principal p,String reason){OrderStatusHistory h=new OrderStatusHistory();h.setId(UUID.randomUUID());h.setTenantId(o.getTenantId());h.setOrderId(o.getId());h.setOldStatus(old);h.setNewStatus(o.getStatus());h.setReason(reason);h.setActorId(p.userId());h.setCreatedAt(Instant.now());orderHistory.save(h);}
@Transactional public CustomerOrder transition(UUID id,OrderTransitionInput x,Principal p){UUID t=tenant(p);permission(p,"ORDER_CREATE");CustomerOrder o=order(id,t);String old=o.getStatus(),next=x.status().toUpperCase(Locale.ROOT);Map<String,Set<String>> allowed=Map.of("CONFIRMED",Set.of("PAYMENT_PENDING","PAID","ON_HOLD","CANCELLED"),"PAYMENT_PENDING",Set.of("PAYMENT_PARTIAL","PAID","ON_HOLD","CANCELLED"),"PAYMENT_PARTIAL",Set.of("PAID","ON_HOLD","CANCELLED"),"PAID",Set.of("MATERIAL_RESERVED","ON_HOLD","CANCELLED"),"MATERIAL_RESERVED",Set.of("INSTALLATION_SCHEDULED","CONFIRMED","ON_HOLD","CANCELLED"),"INSTALLATION_SCHEDULED",Set.of("INSTALLATION_IN_PROGRESS","MATERIAL_RESERVED","ON_HOLD","CANCELLED"),"INSTALLATION_IN_PROGRESS",Set.of("INSTALLED","INSTALLATION_SCHEDULED","ON_HOLD"),"INSTALLED",Set.of("COMMISSIONED"),"COMMISSIONED",Set.of("CLOSED"));if(!allowed.getOrDefault(old,Set.of()).contains(next))throw new ResponseStatusException(HttpStatus.CONFLICT,"Order cannot move from "+old+" to "+next);if("CANCELLED".equals(next)&&reservations.findByTenantIdAndOrderId(t,id).stream().anyMatch(r->"RESERVED".equals(r.getStatus())))throw new ResponseStatusException(HttpStatus.CONFLICT,"Release reserved stock before cancellation");o.setStatus(next);orders.save(o);status(o,old,p,x.reason());return o;}
public List<OrderStatusHistory> orderHistory(UUID id,Principal p){UUID t=tenant(p);permission(p,"ORDER_CREATE");order(id,t);return orderHistory.findByTenantIdAndOrderIdOrderByCreatedAtAsc(t,id);}
public List<InstallationJob> installations(Principal p){UUID t=tenant(p);permission(p,"SURVEY_MANAGE");return installations.findByTenantIdOrderByScheduledAtAsc(t);}
@Transactional public InstallationJob createInstallation(InstallationInput x,Principal p){UUID t=tenant(p);permission(p,"SURVEY_MANAGE");CustomerOrder o=order(x.orderId(),t);if(!Set.of("MATERIAL_RESERVED","INSTALLATION_SCHEDULED").contains(o.getStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Reserve order materials before scheduling installation");if(users.findById(x.assignedEngineerId()).filter(u->t.equals(u.getTenantId())&&u.isEnabled()&&"VENDOR".equals(u.getAccountType())&&u.getRoles().stream().anyMatch(r->Set.of("SERVICE_ENGINEER","INSTALLER","OPERATIONS_MANAGER","VENDOR_ADMIN").contains(r.getName()))).isEmpty())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Engineer must be an enabled same-tenant installer");if(installations.findByTenantIdAndOrderId(t,o.getId()).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"Installation already exists");InstallationJob j=new InstallationJob();j.setId(UUID.randomUUID());j.setTenantId(t);j.setOrderId(o.getId());j.setCustomerId(o.getCustomerId());j.setSiteAddress(x.siteAddress());j.setScheduledAt(x.scheduledAt());j.setAssignedEngineerId(x.assignedEngineerId());j.setTeamName(x.teamName());j.setCapacityKw(x.capacityKw());j.setNotes(x.notes());j.setStatus("SCHEDULED");j.setCreatedAt(Instant.now());installations.save(j);for(String[] a:List.of(new String[]{"SITE_SAFETY","Site safety and access verified"},new String[]{"STRUCTURE","Mounting structure inspected"},new String[]{"MODULES","PV modules installed and secured"},new String[]{"INVERTER","Inverter installed and configured"},new String[]{"WIRING","DC/AC wiring and protection verified"},new String[]{"EARTHING","Earthing and surge protection tested"},new String[]{"DOCUMENTS","Customer handover documents prepared"})){InstallationChecklistItem c=new InstallationChecklistItem();c.setId(UUID.randomUUID());c.setTenantId(t);c.setInstallationId(j.getId());c.setCode(a[0]);c.setTitle(a[1]);c.setMandatory(true);checklist.save(c);}String old=o.getStatus();o.setStatus("INSTALLATION_SCHEDULED");orders.save(o);status(o,old,p,"Installation scheduled");return j;}
private InstallationJob installation(UUID id,UUID t,Principal p){InstallationJob j=installations.findByIdAndTenantId(id,t).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Installation not found"));Set<String> elevated=Set.of("VENDOR_ADMIN","OPERATIONS_MANAGER");if((p.roles()==null||p.roles().stream().noneMatch(elevated::contains))&&!Objects.equals(j.getAssignedEngineerId(),p.userId()))throw new ResponseStatusException(HttpStatus.FORBIDDEN);return j;}
public List<InstallationChecklistItem> checklist(UUID id,Principal p){UUID t=tenant(p);permission(p,"SURVEY_MANAGE");installation(id,t,p);return checklist.findByTenantIdAndInstallationIdOrderByIdAsc(t,id);}
@Transactional public InstallationChecklistItem updateChecklist(UUID id,UUID itemId,ChecklistUpdateInput x,Principal p){UUID t=tenant(p);InstallationJob j=installation(id,t,p);InstallationChecklistItem c=checklist.findByIdAndTenantIdAndInstallationId(itemId,t,id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));c.setCompleted(Boolean.TRUE.equals(x.completed()));c.setEvidenceUrl(x.evidenceUrl());c.setNotes(x.notes());c.setCompletedBy(p.userId());c.setCompletedAt(c.isCompleted()?Instant.now():null);if("SCHEDULED".equals(j.getStatus()))j.setStatus("IN_PROGRESS");installations.save(j);return checklist.save(c);}
@Transactional public InstallationJob reschedule(UUID id,RescheduleInput x,Principal p){UUID t=tenant(p);permission(p,"SURVEY_MANAGE");InstallationJob j=installation(id,t,p);if(!Set.of("SCHEDULED","IN_PROGRESS").contains(j.getStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Installation cannot be rescheduled");j.setScheduledAt(x.scheduledAt());j.setRescheduleReason(x.reason());return installations.save(j);}
@Transactional public InstallationJob commission(UUID id,CommissionInput x,Principal p){UUID t=tenant(p);permission(p,"SURVEY_MANAGE");InstallationJob j=installation(id,t,p);if(checklist.findByTenantIdAndInstallationIdOrderByIdAsc(t,id).stream().anyMatch(c->c.isMandatory()&&!c.isCompleted()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Complete all mandatory checklist items");if(!x.customerSignedOff())throw new ResponseStatusException(HttpStatus.CONFLICT,"Customer sign-off is required");CustomerOrder o=order(j.getOrderId(),t);if(!Set.of("INSTALLATION_IN_PROGRESS","INSTALLED").contains(o.getStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Order must be in installation progress");j.setCustomerSignedOff(true);j.setCommissioningNotes(x.commissioningNotes());j.setStatus("COMMISSIONED");j.setCompletedAt(Instant.now());j.setCommissionedAt(Instant.now());installations.save(j);for(EquipmentInput e:x.equipment()==null?List.<EquipmentInput>of():x.equipment()){Product pr=product(e.productId(),t);Warranty w=new Warranty();w.setId(UUID.randomUUID());w.setTenantId(t);w.setOrderId(o.getId());w.setInstallationId(j.getId());w.setCustomerId(o.getCustomerId());w.setProductId(pr.getId());w.setSerialNumber(e.serialNumber());w.setQuantity(1);w.setStartDate(LocalDate.now());w.setEndDate(LocalDate.now().plusYears(Math.max(1,pr.getWarrantyYears()==null?1:pr.getWarrantyYears())));w.setTerms("Manufacturer warranty applies; retain the product invoice and serial number. Demo catalogue warranty values require vendor verification.");w.setStatus("ACTIVE");w.setActivatedAt(Instant.now());warranties.save(w);}String old=o.getStatus();o.setStatus("COMMISSIONED");orders.save(o);status(o,old,p,"Commissioned with customer sign-off");return j;}
public List<Warranty> warranties(Principal p){UUID t=tenant(p);permission(p,"SURVEY_MANAGE");return warranties.findByTenantIdOrderByStartDateDesc(t);}
}